        new_workplace_id: this.personal_information._fields[1].identity.low,
      })
      .then( () => this.get_personal_info())
      .catch(error => console.log(error));
    },

    get_all_workplaces(){
      this.axios.post('http://authentication.mike.jekt.maximemoreillon.com/get_all_workplaces', {})
      .then(response => {
        this.workplaces = response.data
      })
      .catch(error =>console.log(error));
    },
    */
  }
}
</script>

